// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testFuzz_property(uint256 amount, address caller) public {
        vm.assume(amount > 0);
        vm.assume(caller != address(0));
        vm.assume(caller != address(c));
        vm.assume(caller != address(this));

        uint256 balBeforeCaller = c.getBalance(caller);
        uint256 balBeforeZero = c.getBalance(address(0));

        vm.deal(caller, amount);
        vm.prank(caller);
        c.addToBalance{value: amount}();

        uint256 balAfterCaller = c.getBalance(caller);
        uint256 balAfterZero = c.getBalance(address(0));

        assertTrue(
            balAfterCaller == balBeforeCaller + amount &&
            balAfterZero == balBeforeZero
        );
    }
}
